1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const CURSE_SURCHARGE_PERCENT = 50;
30	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
31	const HIGH_ENCHANTMENT_THRESHOLD = 5;
32	
33	const percentOf = (amount: number, percent: number): number =>
34	  (amount * percent) / 100;
35	
36	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
37	
38	const componentGroupPremium = (count: number): number =>
39	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
40	
41	const firstInsuranceSurcharge = (base: number): number =>
42	  percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
43	
44	const roundPremiumInMhpcoFavor = (premium: number): number =>
45	  Math.ceil(premium);
46	
47	const roundPayoutInMhpcoFavor = (payout: number): number =>
48	  Math.floor(payout);
49	
50	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
51	
52	const isMainItem = (item: Item): boolean => !isComponent(item);
53	
54	const countByType = (items: Item[]): Map<string, number> => {
55	  const counts = new Map<string, number>();
56	  for (const item of items) {
57	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
58	  }
59	  return counts;
60	};
61	
62	const componentsTotalByType = (components: Item[]): number =>
63	  [...countByType(components).values()].reduce(
64	    (total, count) => total + componentGroupPremium(count),
65	    0,
66	  );
67	
68	const itemsBasePremium = (items: Item[]): number => {
69	  const components = items.filter(isComponent);
70	  const mainItems = items.filter(isMainItem);
71	  const mainItemsTotal = mainItems.reduce(
72	    (sum, item) => sum + basePremium(item),
73	    0,
74	  );
75	  return mainItemsTotal + componentsTotalByType(components);
76	};
77	
78	const itemSurcharge = (item: Item): number => {
79	  const base = basePremium(item);
80	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
81	  const highEnchantment =
82	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
83	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
84	      : 0;
85	  return curse + highEnchantment;
86	};
87	
88	const itemSurcharges = (items: Item[]): number =>
89	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
90	
91	const LOYALTY_DISCOUNT_PERCENT = 20;
92	const LOYALTY_THRESHOLD_YEARS = 2;
93	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
94	
95	const loyaltyDiscount = (customer: Customer, base: number): number =>
96	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
97	    ? percentOf(base, LOYALTY_DISCOUNT_PERCENT)
98	    : 0;
99	
100	const followUpContractDiscount = (contractIndex: number, base: number): number =>
101	  contractIndex > 0 ? percentOf(base, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
102	
103	const policyModifiers = (
104	  customer: Customer,
105	  contractIndex: number,
106	  base: number,
107	): number =>
108	  firstInsuranceSurcharge(base) -
109	  loyaltyDiscount(customer, base) -
110	  followUpContractDiscount(contractIndex, base);
111	
112	const validateItemTypes = (items: Item[]): void => {
113	  for (const item of items) {
114	    if (!(item.type in BASE_PREMIUMS)) {
115	      throw new Error(`Unknown item type: ${item.type}`);
116	    }
117	  }
118	};
119	
120	export const quote = (
121	  customer: Customer,
122	  items: Item[],
123	  contractIndex: number,
124	): number => {
125	  validateItemTypes(items);
126	  const base = itemsBasePremium(items);
127	  const total =
128	    base +
129	    policyModifiers(customer, contractIndex, base) +
130	    itemSurcharges(items) +
131	    PROCESSING_FEE;
132	  return roundPremiumInMhpcoFavor(total);
133	};
134	
135	export interface Damage {
136	  itemType: string;
137	  amount: number;
138	}
139	
140	export interface Incident {
141	  cause: string;
142	  damages: Damage[];
143	}
144	
145	export interface ClaimResult {
146	  payout: number;
147	  remainingCap: number;
148	}
149	
150	const DEDUCTIBLE = 100;
151	const CAP_MULTIPLIER = 2;
152	
153	const INSURANCE_VALUES: Record<string, number> = {
154	  sword: 1000,
155	  amulet: 600,
156	  staff: 800,
157	  potion: 400,
158	  rune: 250,
159	  moonstone: 250,
160	};
161	
162	const insuranceValue = (item: Item): number => INSURANCE_VALUES[item.type] ?? 0;
163	
164	const insuranceSum = (items: Item[]): number =>
165	  items.reduce((sum, item) => sum + insuranceValue(item), 0);
166	
167	const HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD = 8;
168	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
169	
170	const reimbursedAmount = (item: Item, amount: number): number =>
171	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_THRESHOLD
172	    ? percentOf(amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
173	    : amount;
174	
175	const damagePayout = (damage: Damage, item: Item): number =>
176	  Math.max(0, reimbursedAmount(item, damage.amount) - DEDUCTIBLE);
177	
178	const insuredItemFor = (items: Item[], damage: Damage): Item =>
179	  items.find((item) => item.type === damage.itemType) as Item;
180	
181	const totalDamagePayout = (items: Item[], damages: Damage[]): number =>
182	  damages.reduce(
183	    (sum, damage) => sum + damagePayout(damage, insuredItemFor(items, damage)),
184	    0,
185	  );
186	
187	const validateDamageCounts = (items: Item[], damages: Damage[]): void => {
188	  const insuredCounts = countByType(items);
189	  const damageCounts = new Map<string, number>();
190	  for (const damage of damages) {
191	    const next = (damageCounts.get(damage.itemType) ?? 0) + 1;
192	    if (next > (insuredCounts.get(damage.itemType) ?? 0)) {
193	      throw new Error(
194	        `More ${damage.itemType} damages than insured items in the policy`,
195	      );
196	    }
197	    damageCounts.set(damage.itemType, next);
198	  }
199	};
200	
201	export const claim = (
202	  items: Item[],
203	  incident: Incident,
204	  priorPayouts: number,
205	): ClaimResult => {
206	  validateDamageCounts(items, incident.damages);
207	  const cap = insuranceSum(items) * CAP_MULTIPLIER;
208	  const remainingBefore = cap - priorPayouts;
209	  const rawPayout = totalDamagePayout(items, incident.damages);
210	  const payout = Math.min(roundPayoutInMhpcoFavor(rawPayout), remainingBefore);
211	  return { payout, remainingCap: remainingBefore - payout };
212	};
